def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def get_divisors(n):
    factors = prime_factorization(n)
    primes = list(factors.keys())
    divs = set()

    def generate_divisors(index, current_divisor):
        if index == len(primes):
            divs.add(current_divisor)
            return

        p = primes[index]
        max_power = factors[p]
        power_of_p = 1
        for i in range(max_power + 1):
            generate_divisors(index + 1, current_divisor * power_of_p)
            power_of_p *= p

    generate_divisors(0, 1)
    return sorted(list(divs))

N = 2021
divisors = get_divisors(N)
print(f"Factors of {N}: {prime_factorization(N)}")
print(f"Divisors of {N}: {divisors}")

